def counter(n):
    i = 0
    while i < n:
        yield i        # 产出并暂停
        i += 1

for x in counter(3):
    print(x)           # 0 1 2

# 生成器表达式（推导式的惰性版）
gen = (i*i for i in range(1000000))
print(sum(gen))        # 不一次性占内存

def log(func):
    def wrapper(*args, **kwargs):
        print(f"→ 调用 {func.__name__}")
        result = func(*args, **kwargs)   # 真正调用原函数
        print(f"← {func.__name__} 完成")
        return result                    # 把原函数的结果返回
    return wrapper

@log                 # 等价于 hi = log(hi)
def hi(name):
    return f"hi {name}"

print(hi("张三"))

def repeat(n):
    def decorator(func):
        def wrapper(*args, **kwargs):
            return [func(*args, **kwargs) for _ in range(n)]
        return wrapper
    return decorator

@repeat(3)
def hi(name):
    return f"hi {name}"

print(hi("张三"))   # ['hi 张三', 'hi 张三', 'hi 张三']

